diff --git a/claude-remote-control/.github/workflows/test.yml b/claude-remote-control/.github/workflows/test.yml
new file mode 100644
index 0000000..cf8544e
--- /dev/null
+++ b/claude-remote-control/.github/workflows/test.yml
@@ -0,0 +1,42 @@
+name: Tests
+
+on:
+  push:
+    branches: [main]
+  pull_request:
+    branches: [main]
+
+jobs:
+  test:
+    runs-on: ubuntu-latest
+
+    steps:
+      - name: Checkout code
+        uses: actions/checkout@v4
+
+      - name: Setup pnpm
+        uses: pnpm/action-setup@v2
+        with:
+          version: 9
+
+      - name: Setup Node.js
+        uses: actions/setup-node@v4
+        with:
+          node-version: '22'
+          cache: 'pnpm'
+
+      - name: Install dependencies
+        run: pnpm install
+
+      - name: Build packages
+        run: pnpm build
+
+      - name: Run tests
+        run: pnpm test
+
+      - name: Upload coverage to Codecov
+        uses: codecov/codecov-action@v4
+        if: always()
+        with:
+          files: ./apps/agent/coverage/lcov.info,./apps/web/coverage/lcov.info,./packages/shared/coverage/lcov.info
+          fail_ci_if_error: false
